import { useEffect, useMemo, useRef, useState } from 'react';
import { DndContext, DragEndEvent, DragOverlay, PointerSensor, TouchSensor, closestCenter, useSensor, useSensors } from '@dnd-kit/core';
import { SortableContext, arrayMove, rectSortingStrategy, useSortable, verticalListSortingStrategy } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { ArrowDownUp, Check, ChevronDown, ChevronRight, Clock3, DownloadCloud, Film, GripVertical, Grid3X3, Headphones, Image, LayoutGrid, List, ListMusic, MoreVertical, Music, Pencil, Play, Plus, Save, Search, Share2, Shuffle, Trash2, Upload, X } from 'lucide-react';
import { api, formatDuration, formatFileSize, Playlist, PlaylistItem, PlaylistSummary, useAddPlaylistItems, useCreatePlaylist, useDeletePlaylist, useFiles, useFolders, usePlaylist, usePlaylists, useRemovePlaylistItem, useReorderPlaylist, useReorderPlaylistCatalog, useUpdatePlaylist, useUploadFile } from '../lib/api';
import { useAppStore } from '../lib/store';
import CustomSelect from './CustomSelect';
import { estimateOfflineStorage, saveFileOffline, savePlaylistOffline } from '../lib/offline';
import { EmptyState, LoadingState } from './StatePanel';

type Kind = 'all' | 'audio' | 'video';
const telegram = () => (window as Window & { Telegram?: { WebApp?: any } }).Telegram?.WebApp;
const openPath = (path: string) => { if (location.pathname !== path) history.pushState({}, '', path); window.dispatchEvent(new PopStateEvent('popstate')); };

export default function PlaylistBrowser() {
    const [path, setPath] = useState(location.pathname);
    const selectedId = Number(path.match(/^\/playlist\/(\d+)/)?.[1]) || null;
    useEffect(() => { const sync = () => setPath(location.pathname); addEventListener('popstate', sync); return () => removeEventListener('popstate', sync); }, []);
    useEffect(() => {
        const back = telegram()?.BackButton;
        if (!back || !selectedId) return;
        const handler = () => openPath('/playlists');
        back.show(); back.onClick(handler);
        return () => { back.offClick(handler); back.hide(); };
    }, [selectedId]);
    return selectedId ? <PlaylistDetail id={selectedId} onBack={() => openPath('/playlists')} /> : <PlaylistIndex />;
}

function PlaylistIndex() {
    const readOnlyWorkspace = Boolean(localStorage.getItem('komod-active-workspace')) && localStorage.getItem('komod-active-workspace-permission') === 'read';
    const { data: playlists = [], isLoading } = usePlaylists();
    const [kind, setKind] = useState<Kind>('all');
    const [query, setQuery] = useState('');
    const [sort, setSort] = useState<'manual' | 'updated' | 'name' | 'count'>('manual');
    const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>('asc');
    const [view, setView] = useState<'grid' | 'dense' | 'list'>(()=>{const saved=localStorage.getItem('komod-playlist-view');return saved==='grid'||saved==='dense'||saved==='list'?saved:'list'});
    const [showSort, setShowSort] = useState(false);
    const [creating, setCreating] = useState(false);
    const [editing, setEditing] = useState<PlaylistSummary | null>(null);
    const [menuPlaylist, setMenuPlaylist] = useState<PlaylistSummary | null>(null);
    const [menuPosition,setMenuPosition]=useState<{x:number;y:number}|null>(null);
    const [pendingDelete,setPendingDelete]=useState<PlaylistSummary|null>(null);
    const [offlinePlaylist,setOfflinePlaylist]=useState<Playlist|null>(null);
    const create = useCreatePlaylist();
    const update = useUpdatePlaylist();
    const removePlaylist = useDeletePlaylist();
    const reorderCatalog = useReorderPlaylistCatalog();
    const { addToast } = useAppStore();
    const visible = useMemo(() => playlists.filter(p => {
        if (kind !== 'all' && (kind === 'audio' ? p.audio_count <= 0 : p.video_count <= 0)) return false;
        const needle=query.trim().toLocaleLowerCase('fa');
        return !needle||[p.name,p.description||'',...(p.preview_names||[])].some(value=>value.toLocaleLowerCase('fa').includes(needle));
    }).sort((a, b) => {
        if (sort === 'manual') return (a.position || 0) - (b.position || 0);
        const value = sort === 'name' ? a.name.localeCompare(b.name, 'fa') : sort === 'count' ? a.item_count - b.item_count || a.updated_at.localeCompare(b.updated_at) : a.updated_at.localeCompare(b.updated_at);
        return sortDirection === 'asc' ? value : -value;
    }), [playlists, kind, query, sort, sortDirection]);
    const sortLabel = sort === 'manual' ? 'ترتیب دستی' : `${sort === 'updated' ? 'تاریخ تغییر' : sort === 'name' ? 'نام' : 'تعداد ترک'} ${sortDirection === 'asc' ? '↑' : '↓'}`;
    const totalItems=playlists.reduce((sum,item)=>sum+item.item_count,0);
    const totalDuration=playlists.reduce((sum,item)=>sum+item.total_duration,0);
    const chooseView=(next:'grid'|'dense'|'list')=>{setView(next);localStorage.setItem('komod-playlist-view',next)};
    const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 6 } }), useSensor(TouchSensor, { activationConstraint: { delay: 180, tolerance: 8 } }));
    const reorderCards = async ({ active, over }: DragEndEvent) => {
        if (readOnlyWorkspace || sort !== 'manual' || view !== 'list' || !over || active.id === over.id) return;
        const oldIndex = visible.findIndex(item => item.id === active.id);
        const newIndex = visible.findIndex(item => item.id === over.id);
        const ordered = arrayMove(visible, oldIndex, newIndex);
        const visibleIds = new Set(visible.map(item => item.id));
        let cursor = 0;
        const merged = playlists.slice().sort((a,b)=>(a.position||0)-(b.position||0)).map(item => visibleIds.has(item.id) ? ordered[cursor++] : item);
        try { await reorderCatalog.mutateAsync(merged.map(item => item.id)); }
        catch { addToast('ذخیره ترتیب پلی‌لیست‌ها انجام نشد.', 'error'); }
    };
    const deleteFromMenu = (playlist: PlaylistSummary) => { setMenuPlaylist(null); setPendingDelete(playlist); };
    const confirmPlaylistDelete = async () => { if(!pendingDelete)return;const target=pendingDelete;setPendingDelete(null);try{await removePlaylist.mutateAsync(target.id);addToast('پلی‌لیست حذف شد');}catch(error:any){addToast(error?.response?.data?.detail||'حذف پلی‌لیست انجام نشد؛ دوباره تلاش کن.','error')} };
    const downloadFromMenu = async (playlist: PlaylistSummary) => {
        setMenuPlaylist(null);
        try { const { data } = await api.get<Playlist>(`/playlists/${playlist.id}`); setOfflinePlaylist(data); }
        catch { addToast('شروع دانلود پلی‌لیست انجام نشد.', 'error'); }
    };
    return <div className="playlist-typography mx-auto w-full max-w-7xl p-4 pb-28 sm:p-6 md:pb-8 lg:p-8">
        <header className="relative overflow-hidden rounded-3xl border border-white/[.08] bg-gradient-to-bl from-primary-500/[.14] via-dark-900/90 to-dark-950 p-5 shadow-xl shadow-black/10 sm:p-7">
            <div className="pointer-events-none absolute -left-10 -top-16 h-48 w-48 rounded-full bg-primary-500/15 blur-3xl"/>
            <div className="relative flex items-center gap-4"><span className="flex h-14 w-14 shrink-0 items-center justify-center rounded-2xl border border-primary-300/15 bg-primary-500/15 text-primary-200 shadow-lg"><Headphones className="h-7 w-7"/></span><div className="min-w-0 flex-1"><h1 className="text-2xl font-black sm:text-3xl">پلی‌لیست‌ها</h1></div>{!readOnlyWorkspace&&<button onClick={()=>setCreating(true)} className="hidden min-h-11 items-center gap-2 rounded-2xl bg-primary-500 px-4 text-sm font-bold text-white shadow-lg shadow-primary-950/25 transition hover:bg-primary-400 sm:flex"><Plus className="h-5 w-5"/>پلی‌لیست تازه</button>}</div>
            <div className="relative mt-5 grid grid-cols-3 gap-2"><span className="rounded-2xl border border-white/[.06] bg-black/10 px-3 py-2.5"><strong className="block text-base text-white">{playlists.length.toLocaleString('fa-IR')}</strong><small className="text-[10px] text-dark-400">پلی‌لیست</small></span><span className="rounded-2xl border border-white/[.06] bg-black/10 px-3 py-2.5"><strong className="block text-base text-white">{totalItems.toLocaleString('fa-IR')}</strong><small className="text-[10px] text-dark-400">فایل قابل پخش</small></span><span className="rounded-2xl border border-white/[.06] bg-black/10 px-3 py-2.5"><strong className="block truncate text-base text-white">{formatDuration(totalDuration)||'—'}</strong><small className="text-[10px] text-dark-400">زمان کل</small></span></div>
        </header>
        <section className="mt-6">
            <div className="mb-3 grid grid-cols-3 gap-1 rounded-2xl border border-white/[.07] bg-dark-900/65 p-1">{([['all','همه'],['audio','صدا'],['video','ویدیو']] as [Kind,string][]).map(([id,label]) => <button key={id} onClick={() => setKind(id)} className={`flex min-h-10 items-center justify-center gap-2 rounded-xl px-2 text-sm font-semibold transition ${kind === id ? 'bg-primary-500 text-white shadow-md shadow-primary-950/25' : 'text-dark-400 hover:bg-white/[.05] hover:text-white'}`}>{id==='all'?<ListMusic className="h-4 w-4"/>:id==='audio'?<Music className="h-4 w-4"/>:<Film className="h-4 w-4"/>}{label}</button>)}</div>
            <div className="relative mb-4 flex w-full flex-wrap items-center gap-1.5 rounded-2xl border border-white/[.08] bg-dark-900/80 p-1.5 shadow-lg shadow-black/10">
                <label className="relative min-w-[12rem] flex-1"><Search className="pointer-events-none absolute right-3 top-1/2 h-4 w-4 -translate-y-1/2 text-dark-500"/><input value={query} onChange={event=>setQuery(event.target.value)} className="h-10 w-full rounded-xl border-0 bg-dark-950/50 pr-9 pl-3 text-sm outline-none placeholder:text-dark-600 focus:ring-1 focus:ring-primary-400/40" placeholder="جست‌وجوی پلی‌لیست…"/></label>
                <div className="relative min-w-[9rem] flex-1 sm:max-w-52">
                    <button onClick={() => setShowSort(value => !value)} className={`flex h-10 w-full items-center justify-center gap-2 rounded-xl px-3 text-xs font-semibold transition ${showSort?'bg-primary-500 text-white shadow-md shadow-primary-950/25':'text-dark-300 hover:bg-white/[.05] hover:text-white'}`}><ArrowDownUp className="h-4 w-4"/><span>{sortLabel}</span><ChevronDown className={`h-3.5 w-3.5 transition ${showSort?'rotate-180':''}`}/></button>
                    {showSort && <div className="absolute inset-x-0 top-full z-40 mt-2 rounded-2xl border border-white/10 bg-dark-900 p-1.5 shadow-2xl">{([['manual','ترتیب دستی'],['updated','تاریخ تغییر'],['name','نام'],['count','تعداد ترک']] as const).map(([value,label]) => <button key={value} onClick={() => { if (sort === value && value !== 'manual') setSortDirection(direction => direction === 'asc' ? 'desc' : 'asc'); else { setSort(value); setSortDirection(value === 'updated' || value === 'count' ? 'desc' : 'asc'); } setShowSort(false); }} className={`flex w-full items-center justify-between rounded-xl px-3 py-2 text-right text-xs ${sort === value ? 'bg-primary-500/15 text-primary-200' : 'text-dark-300 hover:bg-white/[.05]'}`}><span>{label}</span>{sort===value&&value!=='manual'&&<span>{sortDirection==='asc'?'↑':'↓'}</span>}</button>)}</div>}
                </div>
                {!readOnlyWorkspace && <button title="ساخت پلی‌لیست" aria-label="ساخت پلی‌لیست" onClick={() => setCreating(true)} className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-primary-500 text-white shadow-lg shadow-primary-950/25 transition hover:bg-primary-400 sm:hidden"><Plus className="h-5 w-5"/></button>}
                <div className="flex h-10 shrink-0 gap-0.5 rounded-xl border border-white/[.06] bg-dark-950/50 p-1"><button aria-label="نمای کارتی" onClick={() => chooseView('grid')} className={`rounded-lg px-2 transition ${view === 'grid' ? 'bg-primary-500 text-white shadow-sm' : 'text-dark-400 hover:bg-white/[.05] hover:text-white'}`}><LayoutGrid className="h-4 w-4"/></button><button aria-label="نمای کاشی کوچک" onClick={() => chooseView('dense')} className={`rounded-lg px-2 transition ${view === 'dense' ? 'bg-primary-500 text-white shadow-sm' : 'text-dark-400 hover:bg-white/[.05] hover:text-white'}`}><Grid3X3 className="h-4 w-4"/></button><button aria-label="نمای لیستی" onClick={() => chooseView('list')} className={`rounded-lg px-2 transition ${view === 'list' ? 'bg-primary-500 text-white shadow-sm' : 'text-dark-400 hover:bg-white/[.05] hover:text-white'}`}><List className="h-4 w-4"/></button></div>
            </div>
            {isLoading ? <LoadingState label="در حال آماده‌کردن پلی‌لیست‌ها…"/> : visible.length ? <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={reorderCards}><SortableContext items={visible.map(item => item.id)} strategy={rectSortingStrategy}><div className={view === 'grid' ? 'grid gap-4 sm:grid-cols-2 xl:grid-cols-3' : view === 'dense' ? 'grid grid-cols-2 gap-2 sm:grid-cols-3 lg:grid-cols-5' : 'flex flex-col gap-2.5'}>{visible.map(p => <PlaylistCard key={p.id} playlist={p} view={view} manual={!readOnlyWorkspace && sort === 'manual' && view === 'list'} onLongPress={() => {setMenuPosition(null);setMenuPlaylist(p)}} onContextMenu={(x,y)=>{setMenuPosition({x,y});setMenuPlaylist(p)}} />)}</div></SortableContext></DndContext> : <EmptyState icon={<Music/>} title={query?'پلی‌لیستی پیدا نشد':'هنوز پلی‌لیستی اینجا نیست'} description={query?'نام یا فیلتر را تغییر بده و دوباره امتحان کن.':'یک پلی‌لیست بساز و فایل‌های صوتی یا ویدیویی دلخواهت را مرتب کن.'} action={!query&&!readOnlyWorkspace ? <button onClick={() => setCreating(true)} className="btn-primary flex items-center gap-2"><Plus className="h-4 w-4"/>ساخت پلی‌لیست</button> : undefined}/>}
        </section>
        {creating && <PlaylistEditor title="پلی‌لیست تازه" onClose={() => setCreating(false)} onSave={async (name, description) => { const p = await create.mutateAsync({ name, description }); setCreating(false); addToast('پلی‌لیست ساخته شد 🎶'); openPath(`/playlist/${p.id}`); }} />}
        {editing && <PlaylistEditor title="ویرایش پلی‌لیست" initialName={editing.name} initialDescription={editing.description || ''} onClose={() => setEditing(null)} onSave={async (name, description) => { await update.mutateAsync({ id: editing.id, name, description }); setEditing(null); }} />}
        {menuPlaylist && <div className={`fixed inset-0 z-[160] ${menuPosition?'':'flex items-end bg-black/65 backdrop-blur-sm'}`} onClick={() => {setMenuPlaylist(null);setMenuPosition(null)}}><div className={menuPosition?"black-glass-menu fixed w-[min(21rem,calc(100vw-1rem))] rounded-2xl p-3":"w-full rounded-t-3xl border-t border-white/10 bg-dark-900 p-4 pb-[calc(1rem+env(safe-area-inset-bottom))]"} style={menuPosition?{left:Math.max(8,Math.min(menuPosition.x,window.innerWidth-344)),top:Math.max(8,Math.min(menuPosition.y,window.innerHeight-300))}:undefined} onClick={event => event.stopPropagation()}><div className="mx-auto mb-4 h-1 w-12 rounded-full bg-white/20"/><h2 dir="auto" className="mb-3 truncate px-2 font-bold">{menuPlaylist.name}</h2>{!readOnlyWorkspace && <><button className="context-menu-item min-h-14 w-full" onClick={() => { setEditing(menuPlaylist); setMenuPlaylist(null); }}><Pencil className="h-5 w-5"/> ویرایش</button><button className="context-menu-item min-h-14 w-full" onClick={() => openPath(`/playlist/${menuPlaylist.id}?manage=1`)}><Check className="h-5 w-5"/> مدیریت فایل‌ها</button></>}<button className="context-menu-item min-h-14 w-full" onClick={() => void downloadFromMenu(menuPlaylist)}><DownloadCloud className="h-5 w-5"/> دانلود و ذخیره آفلاین</button>{!readOnlyWorkspace && <button className="context-menu-item min-h-14 w-full text-red-300" onClick={() => void deleteFromMenu(menuPlaylist)}><Trash2 className="h-5 w-5"/> حذف پلی‌لیست</button>}</div></div>}
        {pendingDelete&&<PlaylistDeleteConfirm name={pendingDelete.name} pending={removePlaylist.isPending} onClose={()=>setPendingDelete(null)} onConfirm={()=>void confirmPlaylistDelete()}/>}
        {offlinePlaylist&&<OfflinePlaylistPicker playlist={offlinePlaylist} onClose={()=>setOfflinePlaylist(null)} onStart={ids=>{void savePlaylistOffline(offlinePlaylist,undefined,ids);setOfflinePlaylist(null);addToast('فایل‌های انتخاب‌شده به صف ذخیره آفلاین رفتند 📥')}}/>}
    </div>;
}

function PlaylistDeleteConfirm({name,pending,onClose,onConfirm}:{name:string;pending:boolean;onClose:()=>void;onConfirm:()=>void}){
    return <div className="fixed inset-0 z-[220] flex items-end justify-center bg-black/70 p-3 backdrop-blur-sm sm:items-center" onClick={onClose}><section dir="rtl" className="w-full max-w-sm rounded-3xl border border-white/10 bg-dark-900 p-5 text-right shadow-2xl" onClick={event=>event.stopPropagation()}><span className="flex h-11 w-11 items-center justify-center rounded-2xl bg-red-500/10 text-red-300"><Trash2 className="h-5 w-5"/></span><h3 className="mt-4 text-lg font-bold">حذف پلی‌لیست؟</h3><p dir="rtl" className="mt-2 text-sm leading-7 text-dark-400">پلی‌لیست «<bdi dir="auto" className="font-medium text-dark-300">{name}</bdi>» حذف می‌شود؛ فایل‌های داخل کمد باقی می‌مانند.</p><div className="mt-5 grid grid-cols-2 gap-2"><button disabled={pending} className="flex min-h-11 items-center justify-center gap-2 rounded-xl bg-red-600 text-sm font-semibold text-white disabled:opacity-50" onClick={onConfirm}><Trash2 className="h-4 w-4"/>{pending?'در حال حذف…':'حذف'}</button><button disabled={pending} className="btn-secondary min-h-11" onClick={onClose}>بی‌خیال</button></div></section></div>;
}

function OfflinePlaylistPicker({playlist,onClose,onStart}:{playlist:Playlist;onClose:()=>void;onStart:(ids:number[])=>void}){
    const playable=playlist.items.map(item=>item.file).filter(file=>file.file_type==='audio'||file.file_type==='video');
    const [selected,setSelected]=useState<Set<number>>(()=>new Set(playable.map(file=>file.id)));
    const [available,setAvailable]=useState<number|null>(null);
    const all=selected.size===playable.length;
    const selectedBytes=playable.reduce((sum,file)=>sum+(selected.has(file.id)?file.file_size||0:0),0);
    useEffect(()=>{let live=true;void estimateOfflineStorage(selectedBytes).then(value=>{if(live)setAvailable(Number.isFinite(value.available)?value.available:null)});return()=>{live=false}},[selectedBytes]);
    const enough=available===null||available>=selectedBytes;
    return <div className="fixed inset-0 z-[180] flex items-end bg-black/70 backdrop-blur-sm sm:items-center sm:justify-center sm:p-4" onClick={onClose}><section className="flex max-h-[86dvh] w-full max-w-lg flex-col rounded-t-3xl border border-white/10 bg-dark-900 p-4 sm:rounded-3xl" onClick={event=>event.stopPropagation()}><div className="flex items-center gap-3"><div className="min-w-0 flex-1"><h2 className="truncate font-bold">ذخیره آفلاین «{playlist.name}»</h2><p className="mt-1 text-xs text-dark-500">همه یا فقط ترک‌های دلخواهت را انتخاب کن.</p></div><button className="btn-icon" onClick={onClose}><X className="h-4 w-4"/></button></div><button className="mt-4 flex min-h-10 items-center justify-between rounded-xl bg-white/[.04] px-3 text-sm" onClick={()=>setSelected(all?new Set():new Set(playable.map(file=>file.id)))}><span>{all?'لغو انتخاب همه':'انتخاب همه'}</span><span>{selected.size.toLocaleString('fa-IR')} از {playable.length.toLocaleString('fa-IR')}</span></button><div className={`mt-2 flex items-center justify-between rounded-xl px-3 py-2 text-xs ${enough?'bg-primary-500/[.08] text-dark-300':'bg-red-500/10 text-red-200'}`}><span>حجم تقریبی: {formatFileSize(selectedBytes)}</span><span>{available===null?'فضای آزاد نامشخص':`آزاد: ${formatFileSize(available)}`}</span></div><div className="mt-2 min-h-0 flex-1 overflow-y-auto">{playable.map(file=><button key={file.id} onClick={()=>setSelected(previous=>{const next=new Set(previous);next.has(file.id)?next.delete(file.id):next.add(file.id);return next})} className="flex min-h-14 w-full items-center gap-3 border-b border-white/[.05] px-2 text-right"><span className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-md border ${selected.has(file.id)?'border-primary-400 bg-primary-500 text-white':'border-white/20'}`}>{selected.has(file.id)&&<Check className="h-4 w-4"/>}</span><span className="min-w-0 flex-1 truncate text-sm">{file.file_name}</span><small className="text-dark-500">{file.file_type==='video'?'ویدیو':'صدا'}</small></button>)}</div><button disabled={!selected.size||!enough} onClick={()=>onStart([...selected])} className="btn-primary mt-4 min-h-11 disabled:opacity-40">{enough?`ذخیره ${selected.size.toLocaleString('fa-IR')} فایل`:'فضای کافی نیست'}</button></section></div>;
}

function PlaylistCard({ playlist, view, manual, onLongPress, onContextMenu }: { playlist: PlaylistSummary; view: 'grid' | 'dense' | 'list'; manual: boolean; onLongPress: () => void; onContextMenu:(x:number,y:number)=>void }) {
    const grid = view === 'grid';
    const dense = view === 'dense';
    const sortable = useSortable({ id: playlist.id, disabled: !manual });
    const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
    const held = useRef(false);
    const clear = () => { if (timer.current) clearTimeout(timer.current); timer.current = null; };
    const start = () => { held.current = false; timer.current = setTimeout(() => { held.current = true; onLongPress(); }, 550); };
    return <article ref={sortable.setNodeRef} onContextMenu={event=>{event.preventDefault();event.stopPropagation();onContextMenu(event.clientX,event.clientY)}} style={{transform:CSS.Transform.toString(sortable.transform),transition:sortable.transition}} dir="rtl" onPointerDown={start} onPointerUp={clear} onPointerCancel={clear} onPointerLeave={clear} onClick={() => { if (held.current) { held.current=false; return; } openPath(`/playlist/${playlist.id}`); }} className={`group relative flex cursor-pointer overflow-hidden rounded-3xl border border-white/[.07] bg-gradient-to-bl from-dark-800/75 to-dark-950/80 text-right shadow-lg shadow-black/5 transition duration-200 hover:-translate-y-0.5 hover:border-primary-400/25 hover:shadow-xl hover:shadow-black/15 ${sortable.isDragging?'z-20 opacity-60 shadow-2xl':''} ${grid || dense ? 'flex-col items-stretch p-2.5' : 'min-h-24 items-center gap-3 p-2.5 sm:gap-4'}`}>
        <Collage urls={playlist.cover_urls} customUrl={playlist.cover_file_id ? playlist.cover_url : null} large={grid || dense} medium={!grid&&!dense}/>
        <div className={`min-w-0 flex-1 ${grid?'px-1 pb-1':dense?'px-0.5 pb-0.5':''}`}>
            <strong dir="auto" className={`block min-w-0 truncate font-bold text-white ${grid ? 'text-lg' : dense ? 'text-sm' : 'text-base sm:text-lg'}`}>{playlist.name}</strong>
            {!dense&&playlist.description&&<p dir="auto" className={`mt-1 line-clamp-1 text-xs leading-5 text-dark-400 ${grid?'sm:line-clamp-2':''}`}>{playlist.description}</p>}
            <div className={`mt-2 flex flex-wrap items-center gap-x-3 gap-y-1 text-[11px] text-dark-400 ${dense?'text-[10px]':''}`}><span className="flex items-center gap-1"><ListMusic className="h-3.5 w-3.5 text-primary-300"/>{playlist.item_count.toLocaleString('fa-IR')} مورد</span>{playlist.audio_count>0&&<span className="flex items-center gap-1"><Music className="h-3.5 w-3.5"/>{playlist.audio_count.toLocaleString('fa-IR')}</span>}{playlist.video_count>0&&<span className="flex items-center gap-1"><Film className="h-3.5 w-3.5"/>{playlist.video_count.toLocaleString('fa-IR')}</span>}</div>
            {!dense&&<div className="mt-2 flex items-center gap-3 border-t border-white/[.05] pt-2 text-[10px] text-dark-500"><span className="flex items-center gap-1"><Clock3 className="h-3 w-3"/>{formatDuration(playlist.total_duration)||'بدون زمان'}</span></div>}
            {grid&&<div className="mt-2 grid gap-1">{playlist.preview_names?.length ? playlist.preview_names.slice(0,2).map((name,index) => <span key={index} dir="auto" className="truncate text-[11px] text-dark-500">{(index+1).toLocaleString('fa-IR')}. {name}</span>) : <span className="text-[11px] text-dark-500">برای شروع، چند فایل اضافه کن</span>}</div>}
        </div>
        <div className={`flex shrink-0 items-center gap-0.5 ${grid||dense?'absolute left-3 top-3 z-10 rounded-xl border border-white/10 bg-black/55 p-0.5 shadow-lg backdrop-blur-md':''}`}><button type="button" aria-label="گزینه‌های پلی‌لیست" title="گزینه‌ها" onPointerDown={event=>event.stopPropagation()} onClick={event=>{event.stopPropagation();if(window.matchMedia('(min-width: 640px)').matches)onContextMenu(event.clientX,event.clientY);else onLongPress()}} className={`flex h-10 w-9 shrink-0 items-center justify-center rounded-xl text-white transition hover:bg-black/30 ${!grid&&!dense?'border border-white/[.07] bg-dark-950/45 text-dark-300':''}`}><MoreVertical className="h-4 w-4"/></button>{manual && <button {...sortable.attributes} {...sortable.listeners} onPointerDown={event => event.stopPropagation()} onClick={event => event.stopPropagation()} className="flex h-10 w-8 shrink-0 touch-none items-center justify-center rounded-xl text-dark-500 hover:bg-white/[.05] hover:text-white" title="برای تغییر ترتیب بکش"><GripVertical className="h-5 w-5"/></button>}</div>
    </article>;
}

function CoverTile({ src, className = '' }: { src: string; className?: string }) {
    const [failed, setFailed] = useState(false);
    useEffect(() => setFailed(false), [src]);
    return failed ? <span className={`${className} flex items-center justify-center bg-gradient-to-br from-primary-500/25 via-dark-800 to-pink-500/20 text-2xl`}>🎶</span> : <img loading="lazy" decoding="async" src={src} style={{ imageRendering: 'auto' }} className={className} alt="" onError={() => setFailed(true)}/>;
}

function Collage({ urls, customUrl, large = false, medium = false, square = false }: { urls: string[]; customUrl?: string | null; large?: boolean; medium?: boolean; square?: boolean }) {
    const token = localStorage.getItem('access_token');
    const auth = (url: string) => `${url}${url.includes('?') ? '&' : '?'}token=${encodeURIComponent(token || '')}`;
    return <span className={`grid shrink-0 grid-cols-2 overflow-hidden rounded-2xl bg-gradient-to-br from-primary-500/30 to-pink-500/20 shadow-lg shadow-black/20 ${square?'aspect-square w-full':large ? 'aspect-[4/3] w-full' : medium?'h-20 w-20 sm:h-24 sm:w-24':'h-16 w-16'}`}>{customUrl ? <CoverTile src={auth(customUrl)} className="col-span-2 h-full w-full object-cover"/> : urls.length ? urls.slice(0,4).map((url,i) => <CoverTile key={i} src={auth(url)} className="h-full w-full object-cover"/>) : <span className="col-span-2 flex items-center justify-center bg-gradient-to-br from-primary-500/20 via-dark-800 to-pink-500/20 text-3xl"><Music className="h-8 w-8"/></span>}</span>;
}

function CoverPreview({ playlist }: { playlist: Playlist }) {
    const token = localStorage.getItem('access_token');
    const [failed, setFailed] = useState(false);
    useEffect(() => setFailed(false), [playlist.cover_url]);
    if (!playlist.cover_file_id || !playlist.cover_url || failed) return <span className="block h-44 w-44 overflow-hidden rounded-3xl border border-white/10 shadow-2xl shadow-black/40 sm:h-52 sm:w-52"><Collage urls={playlist.cover_urls} square/></span>;
    return <span className="block h-44 w-44 shrink-0 overflow-hidden rounded-3xl border border-white/10 bg-dark-800 shadow-2xl shadow-black/40 sm:h-52 sm:w-52"><img loading="eager" decoding="async" src={`${playlist.cover_url}${playlist.cover_url.includes('?')?'&':'?'}token=${encodeURIComponent(token || '')}`} style={{ imageRendering: 'auto' }} className="h-full w-full object-cover" alt="کاور پلی‌لیست" onError={() => setFailed(true)}/></span>;
}

function PlaylistDetail({ id, onBack }: { id: number; onBack: () => void }) {
    const readOnlyWorkspace = Boolean(localStorage.getItem('komod-active-workspace')) && localStorage.getItem('komod-active-workspace-permission') === 'read';
    const { data: playlist, isLoading } = usePlaylist(id);
    const reorder = useReorderPlaylist(); const remove = useRemovePlaylistItem(); const del = useDeletePlaylist();
    const { startQueue, addToast, isPlayerMinimized, previewFile } = useAppStore();
    const [adding, setAdding] = useState(false); const [confirmDelete,setConfirmDelete]=useState(false); const [editing, setEditing] = useState(false); const [coverPicker, setCoverPicker] = useState(false); const [menu, setMenu] = useState(false); const [managing, setManaging] = useState(() => new URLSearchParams(location.search).get('manage') === '1'); const [selected, setSelected] = useState<Set<number>>(new Set()); const [activeItem, setActiveItem] = useState<number | null>(null); const [orderedItems, setOrderedItems] = useState<PlaylistItem[]>([]);
    useEffect(() => { if (playlist) setOrderedItems(playlist.items); }, [playlist?.id, playlist?.items]);
    const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 4 } }), useSensor(TouchSensor, { activationConstraint: { delay: 80, tolerance: 5 } }));
    if (isLoading || !playlist) return <div className="m-6 h-52 animate-pulse rounded-3xl bg-dark-800"/>;
    const play = (index = 0) => startQueue(orderedItems.map(x => x.file), index);
    const playShuffled = () => {
        const files=orderedItems.map(item=>item.file);
        for(let index=files.length-1;index>0;index--){const target=Math.floor(Math.random()*(index+1));[files[index],files[target]]=[files[target],files[index]]}
        if(files.length)startQueue(files,0);
    };
    const toggleSelected = (itemId: number) => setSelected(previous => { const next = new Set(previous); next.has(itemId) ? next.delete(itemId) : next.add(itemId); return next; });
    const selectAll = () => setSelected(selected.size === orderedItems.length ? new Set() : new Set(orderedItems.map(item => item.id)));
    const playSelected = () => { const files = orderedItems.filter(item => selected.has(item.id)).map(item => item.file); if (files.length) startQueue(files, 0); };
    const saveSelectedOffline = async () => { const files = orderedItems.filter(item => selected.has(item.id)).map(item => item.file); if (!files.length) return; try { await Promise.all(files.map(file => saveFileOffline(file))); addToast(`${files.length.toLocaleString('fa-IR')} فایل برای پخش آفلاین ذخیره شد 📥`); } catch { addToast('ذخیره آفلاین بعضی فایل‌ها انجام نشد', 'error'); } };
    const deleteSelected = async () => { try { await Promise.all([...selected].map(itemId => remove.mutateAsync({ id, itemId }))); setSelected(new Set()); setManaging(false); } catch { addToast('حذف بعضی ترک‌ها انجام نشد', 'error'); } };
    const dragEnd = async ({ active, over }: DragEndEvent) => {
        setActiveItem(null);
        if (readOnlyWorkspace || !over || active.id === over.id) return;
        const oldIndex = orderedItems.findIndex(item => String(item.id) === String(active.id));
        const newIndex = orderedItems.findIndex(item => String(item.id) === String(over.id));
        if (oldIndex < 0 || newIndex < 0) return;
        const previousItems = orderedItems;
        const nextItems = arrayMove(previousItems, oldIndex, newIndex).map((item, position) => ({ ...item, position }));
        setOrderedItems(nextItems);
        try {
            const saved = await reorder.mutateAsync({ id, itemIds: nextItems.map(item => item.id) });
            setOrderedItems(saved.items);
        } catch {
            setOrderedItems(previousItems);
            addToast('ذخیرهٔ ترتیب انجام نشد', 'error');
        }
    };
    const requestDelete=()=>setConfirmDelete(true); const confirmDetailDelete=async()=>{setConfirmDelete(false);try{await del.mutateAsync(id);addToast('پلی‌لیست حذف شد');onBack()}catch(error:any){addToast(error?.response?.data?.detail||'حذف پلی‌لیست انجام نشد؛ دوباره تلاش کن.','error')}};
    return <div className="playlist-typography mx-auto w-full max-w-5xl p-4 pb-28 sm:p-6 md:pb-8 lg:p-8">
        {managing ? <div className="mb-4 flex items-center gap-3 rounded-2xl border border-primary-400/15 bg-dark-900/90 p-2.5 shadow-lg"><button className="btn-icon" onClick={() => { setManaging(false); setSelected(new Set()); }} aria-label="پایان مدیریت"><X className="h-5 w-5"/></button><div className="min-w-0 flex-1"><strong className="block text-sm sm:text-base">مدیریت فایل‌ها</strong><span className="text-[10px] text-dark-500">{selected.size.toLocaleString('fa-IR')} مورد انتخاب شده</span></div><button className="rounded-xl border border-white/10 px-3 py-2 text-xs text-dark-200 transition hover:bg-white/[.05]" onClick={selectAll}>{selected.size === orderedItems.length&&orderedItems.length ? 'لغو همه' : 'انتخاب همه'}</button></div> : <header className="relative overflow-hidden rounded-[2rem] border border-white/[.08] bg-gradient-to-bl from-primary-500/[.13] via-dark-900/90 to-dark-950 p-4 shadow-2xl shadow-black/10 sm:p-6"><div className="pointer-events-none absolute -left-20 -top-24 h-64 w-64 rounded-full bg-primary-500/15 blur-3xl"/><div className="absolute right-3 top-3 z-10"><button className="flex h-10 w-10 items-center justify-center rounded-xl border border-white/[.05] bg-black/10 text-primary-200 transition hover:bg-primary-500/15 active:scale-95" onClick={onBack} title="بازگشت" aria-label="بازگشت به پلی‌لیست‌ها"><ChevronRight className="h-5 w-5"/></button></div>{!readOnlyWorkspace&&<button className="absolute left-3 top-3 z-10 flex h-10 w-10 items-center justify-center rounded-xl border border-white/[.05] bg-black/10 text-primary-200 transition hover:bg-primary-500/15 active:scale-95" onClick={()=>setMenu(true)} aria-label="گزینه‌های پلی‌لیست"><MoreVertical className="h-5 w-5"/></button>}<div className="relative flex flex-col items-center gap-5 pt-9 text-center md:flex-row md:items-end md:pt-0 md:text-right"><CoverPreview playlist={playlist}/><div className="min-w-0 w-full flex-1"><span className="text-[10px] font-bold uppercase tracking-wider text-primary-300">پلی‌لیست</span><h1 dir="auto" className="mt-1 truncate text-2xl font-black sm:text-3xl md:text-4xl">{playlist.name}</h1>{playlist.description&&<p dir="auto" className="mt-2 max-w-2xl text-sm leading-7 text-dark-300">{playlist.description}</p>}<div className="mt-3 flex flex-wrap items-center justify-center gap-x-4 gap-y-2 text-xs text-dark-300 md:justify-start"><span className="flex items-center gap-1.5"><ListMusic className="h-4 w-4 text-primary-300"/>{playlist.item_count.toLocaleString('fa-IR')} مورد</span>{playlist.audio_count>0&&<span className="flex items-center gap-1.5"><Music className="h-4 w-4"/>{playlist.audio_count.toLocaleString('fa-IR')} صدا</span>}{playlist.video_count>0&&<span className="flex items-center gap-1.5"><Film className="h-4 w-4"/>{playlist.video_count.toLocaleString('fa-IR')} ویدیو</span>}<span className="flex items-center gap-1.5"><Clock3 className="h-4 w-4"/>{formatDuration(playlist.total_duration)||'زمان نامشخص'}</span></div><div className="mt-5 grid w-full grid-cols-2 gap-2.5 md:max-w-xl"><button disabled={!orderedItems.length} className="btn-primary flex min-h-12 items-center justify-center gap-2 rounded-2xl !border-0 text-sm shadow-lg disabled:opacity-40 md:min-h-14 md:text-base" title="پخش پلی‌لیست" onClick={()=>play()}><Play className="h-5 w-5 fill-current"/>پخش از ابتدا</button><button disabled={orderedItems.length<2} className="btn-secondary flex min-h-12 items-center justify-center gap-2 rounded-2xl text-sm shadow-lg disabled:opacity-40 md:min-h-14 md:text-base" title="پخش با ترتیب تصادفی" onClick={playShuffled}><Shuffle className="h-5 w-5"/>تصادفی</button></div></div></div></header>}
        <section className="mt-5">
        <DndContext sensors={sensors} collisionDetection={closestCenter} onDragStart={({ active }) => setActiveItem(Number(active.id))} onDragCancel={() => setActiveItem(null)} onDragEnd={dragEnd}><SortableContext items={orderedItems.map(x => x.id)} strategy={verticalListSortingStrategy}><div className="grid gap-2">{orderedItems.map((item,index) => <TrackRow key={item.id} item={item} index={index} manage={managing} selected={selected.has(item.id)} reorderDisabled={reorder.isPending || readOnlyWorkspace || !managing} onToggle={() => toggleSelected(item.id)} onPlay={() => play(index)} onLongPress={() => { if (!readOnlyWorkspace) { setManaging(true); setSelected(new Set([item.id])); } }}/>)}</div></SortableContext><DragOverlay>{activeItem ? <div className="rounded-2xl border border-primary-500/40 bg-dark-800 px-4 py-3 shadow-2xl">{orderedItems.find(item => item.id === activeItem)?.file.file_name}</div> : null}</DragOverlay></DndContext>
        {!orderedItems.length && <button disabled={readOnlyWorkspace} onClick={() => setAdding(true)} className="flex w-full flex-col items-center rounded-3xl border border-dashed border-white/10 bg-dark-900/35 px-4 py-14 text-dark-300 transition hover:border-primary-400/25 hover:bg-primary-500/[.04] disabled:cursor-default"><span className="flex h-14 w-14 items-center justify-center rounded-2xl bg-primary-500/10 text-primary-200"><ListMusic className="h-7 w-7"/></span><strong className="mt-4 text-sm text-dark-200">این پلی‌لیست هنوز خالی است</strong>{!readOnlyWorkspace && <span className="mt-1 text-xs text-primary-300">اولین آهنگ یا ویدیو را اضافه کن</span>}</button>}</section>
        {managing && <div className={`fixed inset-x-2 z-[130] mx-auto flex max-w-3xl items-center justify-around rounded-2xl border border-white/10 bg-dark-900/95 px-2 py-2.5 shadow-2xl backdrop-blur-xl md:inset-x-0 ${isPlayerMinimized && previewFile && (previewFile.file_type === 'audio' || previewFile.file_type === 'video') ? 'bottom-[calc(10rem+env(safe-area-inset-bottom))] md:bottom-20' : 'bottom-[calc(5.5rem+env(safe-area-inset-bottom))] md:bottom-3'}`}><button className="flex min-h-11 flex-col items-center justify-center gap-1 px-2 text-[10px] text-dark-200" onClick={() => setAdding(true)}><Plus className="h-5 w-5"/>افزودن</button><button disabled={!selected.size} className="flex min-h-11 flex-col items-center justify-center gap-1 px-2 text-[10px] text-dark-200 disabled:opacity-30" onClick={playSelected}><Play className="h-5 w-5"/>پخش انتخاب‌ها</button><button disabled={!selected.size} className="flex min-h-11 flex-col items-center justify-center gap-1 px-2 text-[10px] text-dark-200 disabled:opacity-30" onClick={() => void saveSelectedOffline()}><DownloadCloud className="h-5 w-5"/>آفلاین</button><button className="flex min-h-11 flex-col items-center justify-center gap-1 px-2 text-[10px] text-dark-200" onClick={() => { navigator.clipboard?.writeText(window.location.href); addToast('پیوند پلی‌لیست کپی شد'); }}><Share2 className="h-5 w-5"/>اشتراک</button><button disabled={!selected.size} className="flex min-h-11 flex-col items-center justify-center gap-1 px-2 text-[10px] text-red-300 disabled:opacity-30" onClick={() => void deleteSelected()}><Trash2 className="h-5 w-5"/>حذف</button></div>}
        {menu && <div className="fixed inset-0 z-[140] flex items-end bg-black/60 backdrop-blur-sm" onClick={() => setMenu(false)}><div className="w-full rounded-t-3xl border-t border-white/10 bg-dark-900 p-4 pb-[calc(1rem+env(safe-area-inset-bottom))]" onClick={event => event.stopPropagation()}><div className="mx-auto mb-4 h-1 w-12 rounded-full bg-white/20"/><button className="context-menu-item min-h-14 w-full py-4 text-base" onClick={() => { setEditing(true); setMenu(false); }}><Pencil className="h-5 w-5"/> تغییر نام</button><button className="context-menu-item min-h-14 w-full py-4 text-base" onClick={() => { setAdding(true); setMenu(false); }}><Plus className="h-5 w-5"/> افزودن فایل</button><button className="context-menu-item min-h-14 w-full py-4 text-base" onClick={() => { setCoverPicker(true); setMenu(false); }}><Image className="h-5 w-5"/> تغییر کاور</button><button className="context-menu-item min-h-14 w-full py-4 text-base" onClick={() => { setManaging(true); setMenu(false); }}><Check className="h-5 w-5"/> مدیریت</button><button className="context-menu-item min-h-14 w-full py-4 text-base text-red-300" onClick={() => { setMenu(false); requestDelete(); }}><Trash2 className="h-5 w-5"/> حذف پلی‌لیست</button></div></div>}
        {confirmDelete&&<PlaylistDeleteConfirm name={playlist.name} pending={del.isPending} onClose={()=>setConfirmDelete(false)} onConfirm={()=>void confirmDetailDelete()}/>}
        {adding && <BulkAdd playlist={playlist} onClose={() => setAdding(false)}/>} {editing && <EditPlaylist playlist={playlist} close={() => setEditing(false)}/>} {coverPicker && <CoverPicker playlist={playlist} onClose={() => setCoverPicker(false)}/>} 
    </div>;
}

function TrackRow({ item, index, manage, selected, reorderDisabled, onToggle, onPlay, onLongPress }: { item: PlaylistItem; index:number; manage: boolean; selected: boolean; reorderDisabled: boolean; onToggle: () => void; onPlay: () => void; onLongPress: () => void }) {
    const sortable = useSortable({ id: item.id, disabled: reorderDisabled }); const token = localStorage.getItem('access_token');
    const [thumbnailFailed, setThumbnailFailed] = useState(false);
    const longPressTimer = useRef<ReturnType<typeof setTimeout> | null>(null); const suppressClick = useRef(false);
    const thumbnail = item.file.thumbnail_url ? `${item.file.thumbnail_url}${item.file.thumbnail_url.includes('?') ? '&' : '?'}token=${encodeURIComponent(token || '')}` : null;
    const title = item.file.file_name.replace(/\.[^/.]+$/, '');
    const clearLongPress = () => { if (longPressTimer.current) { clearTimeout(longPressTimer.current); longPressTimer.current = null; } };
    const startLongPress = (event: React.PointerEvent) => { if (event.pointerType !== 'touch' || manage) return; suppressClick.current = false; longPressTimer.current = setTimeout(() => { suppressClick.current = true; onLongPress(); }, 500); };
    return <div dir="rtl" ref={sortable.setNodeRef} style={{ transform: CSS.Transform.toString(sortable.transform), transition: sortable.isDragging ? undefined : sortable.transition }} onContextMenu={event=>{event.preventDefault();if(!manage)onLongPress()}} onPointerDown={startLongPress} onPointerUp={clearLongPress} onPointerCancel={clearLongPress} onPointerLeave={clearLongPress} onClick={() => { if (suppressClick.current) { suppressClick.current = false; return; } manage ? onToggle() : onPlay(); }} className={`group flex min-h-[76px] cursor-pointer items-center gap-3 rounded-2xl border px-2.5 py-2.5 transition ${selected ? 'border-primary-400/30 bg-primary-500/[.09]' : 'border-white/[.06] bg-dark-900/55 hover:border-white/[.11] hover:bg-dark-800/70'} ${sortable.isDragging ? 'z-10 opacity-60 shadow-xl' : ''}`}>
        {manage ? <span className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-lg border ${selected ? 'border-primary-400 bg-primary-500 text-white' : 'border-white/20 text-transparent'}`}><Check className="h-4 w-4"/></span> : <span className="w-6 shrink-0 text-center text-xs tabular-nums text-dark-500">{(index+1).toLocaleString('fa-IR')}</span>}
        <span className="relative flex h-14 w-14 shrink-0 items-center justify-center overflow-hidden rounded-xl bg-gradient-to-br from-primary-500/20 via-dark-800 to-pink-500/15 text-primary-200 shadow-md">{thumbnail && !thumbnailFailed ? <img loading="lazy" decoding="async" src={thumbnail} style={{ imageRendering: 'auto' }} alt="" className="h-full w-full object-cover" onError={() => setThumbnailFailed(true)}/> : item.file.file_type === 'video' ? <Film className="h-6 w-6"/> : <Music className="h-6 w-6"/>}{!manage&&<span className="absolute inset-0 flex items-center justify-center bg-black/45 opacity-0 transition group-hover:opacity-100"><Play className="h-5 w-5 fill-white text-white"/></span>}</span>
        <span dir="auto" className="min-w-0 flex-1 text-right"><strong className="block truncate text-sm font-semibold text-white">{title}</strong><span className="mt-1 flex flex-wrap items-center gap-1.5 text-[11px] text-dark-500"><span>{item.file.file_type === 'video' ? 'ویدیو' : 'صدا'}</span>{item.file.duration>0&&<><span>·</span><span dir="ltr">{formatDuration(item.file.duration)}</span></>}{item.file.file_size>0&&<><span>·</span><span>{formatFileSize(item.file.file_size)}</span></>}</span></span>
        {manage ? <button {...sortable.attributes} {...sortable.listeners} disabled={reorderDisabled} onClick={event => event.stopPropagation()} className="flex h-11 w-9 shrink-0 touch-none items-center justify-center rounded-xl text-dark-500 hover:bg-white/[.05] hover:text-dark-200 disabled:opacity-40" title={reorderDisabled?'در حال ذخیره ترتیب':'برای جابه‌جایی بکش'}><GripVertical className="h-5 w-5"/></button> : <button type="button" onClick={event=>{event.stopPropagation();onPlay()}} className="hidden h-10 w-10 shrink-0 items-center justify-center rounded-full bg-primary-500/10 text-primary-200 transition hover:bg-primary-500 hover:text-white sm:flex" aria-label="پخش"><Play className="h-4 w-4 fill-current"/></button>}
    </div>;
}

function BulkAdd({ playlist, onClose }: { playlist: Playlist; onClose: () => void }) {
    const [query,setQuery] = useState(''); const [folder,setFolder] = useState<number|null>(null); const [kind,setKind] = useState<Kind>('all'); const [selected,setSelected] = useState<Set<number>>(new Set());
    const { data } = useFiles(folder, kind === 'all' ? 'audio,video' : kind, query || undefined, 1, 'name:asc'); const { data: folders=[] } = useFolders(null); const add = useAddPlaylistItems();
    const existing = useMemo(() => new Set(playlist.items.map(x => x.file.id)), [playlist]);
    const submit = async () => { const ids=[...selected]; const duplicates=ids.filter(fileId => existing.has(fileId)); const run=async(allowDuplicates:boolean)=>{await add.mutateAsync({id:playlist.id,fileIds:ids,allowDuplicates});onClose()}; if (!duplicates.length) return run(false); const message='بعضی فایل‌ها قبلاً اضافه شده‌اند؛ دوباره هم اضافه شوند؟'; if(telegram()?.showConfirm) telegram().showConfirm(message,(yes:boolean)=>void run(yes)); else void run(confirm(message)); };
    const visibleFiles = data?.files || [];
    const selectableFiles = visibleFiles.filter(file => !existing.has(file.id));
    const allVisibleSelected = selectableFiles.length > 0 && selectableFiles.every(file => selected.has(file.id));
    const toggleAll = () => setSelected(previous => { const next = new Set(previous); visibleFiles.filter(file => !existing.has(file.id)).forEach(file => allVisibleSelected ? next.delete(file.id) : next.add(file.id)); return next; });
    return <div className="fixed inset-0 z-[150] flex items-end bg-black/70 backdrop-blur-sm" onClick={onClose}><div className="mx-auto flex max-h-[88vh] w-full max-w-2xl flex-col rounded-t-3xl border border-white/10 bg-dark-900 p-4 pb-[calc(1rem+env(safe-area-inset-bottom))]" onClick={e=>e.stopPropagation()}><div className="mx-auto mb-3 h-1 w-12 rounded-full bg-white/20"/><div className="flex items-center justify-between"><div><h2 className="text-lg font-bold">افزودن فایل‌ها</h2><p className="mt-1 text-xs text-dark-500">فایل‌های صدا و ویدیو را انتخاب کن.</p></div><button className="btn-icon" onClick={onClose}><X className="h-5 w-5"/></button></div><div className="relative mt-4"><Search className="absolute right-3 top-3 h-4 w-4 text-dark-500"/><input className="input w-full pr-9" placeholder="جست‌وجوی آهنگ یا ویدیو…" value={query} onChange={e=>setQuery(e.target.value)}/></div><div className="mt-3 grid grid-cols-3 rounded-xl border border-white/[.07] bg-dark-800/70 p-1">{([['all','همه'],['audio','🎵 آهنگ'],['video','🎬 ویدیو']] as [Kind,string][]).map(([value,label]) => <button key={value} onClick={() => setKind(value)} className={`rounded-lg px-2 py-2 text-xs ${kind === value ? 'bg-primary-500/20 text-primary-200' : 'text-dark-400'}`}>{label}</button>)}</div><CustomSelect className="mt-3" label="کشوی فایل‌ها" value={folder ?? 0} onChange={value => setFolder(value === 0 ? null : Number(value))} options={[{ value: 0, label: 'فایل‌های بیرون از کشو' }, ...folders.map(item => ({ value: item.id, label: item.name }))]}/><div className="mt-3 flex items-center justify-between border-b border-white/[.06] pb-2"><span className="text-xs text-dark-400">{selected.size.toLocaleString('fa-IR')} مورد انتخاب شده</span><button className="rounded-lg px-2 py-1 text-xs text-primary-300 hover:bg-primary-500/10" onClick={toggleAll}>{allVisibleSelected ? 'لغو انتخاب همه' : 'انتخاب همه'}</button></div><div className="min-h-0 flex-1 space-y-1 overflow-y-auto">{visibleFiles.map(file=><button key={file.id} disabled={existing.has(file.id)} onClick={()=>setSelected(prev=>{if(existing.has(file.id)) return prev; const n=new Set(prev);n.has(file.id)?n.delete(file.id):n.add(file.id);return n})} className={`flex w-full items-center gap-3 rounded-xl border p-3 text-right disabled:cursor-not-allowed disabled:opacity-55 ${selected.has(file.id)?'border-primary-500/40 bg-primary-500/10':'border-transparent hover:bg-white/[.04]'}`}><span className={`h-5 w-5 rounded border ${selected.has(file.id)?'border-primary-400 bg-primary-500':'border-white/20'}`}/><span>{file.file_type==='video'?<Film className="h-4 w-4"/>:<Music className="h-4 w-4"/>}</span><span className="min-w-0 flex-1 truncate text-sm">{file.file_name}</span>{existing.has(file.id)&&<span className="text-[10px] text-amber-300">قبلاً افزوده شده</span>}</button>)}</div><button disabled={!selected.size||add.isPending} className="btn-primary mt-4" onClick={submit}>افزودن ({selected.size.toLocaleString('fa-IR')})</button></div></div>;
}

function CoverPicker({ playlist, onClose }: { playlist: Playlist; onClose: () => void }) {
    const { data } = useFiles(null, 'image', undefined, 1, 'created:desc', false, true);
    const update = useUpdatePlaylist(); const upload = useUploadFile();
    const uploadCover = async (event: React.ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; event.target.value = ''; if (!file || !file.type.startsWith('image/')) return; const uploaded = await upload.mutateAsync({ file, folderId: null }); await update.mutateAsync({ id: playlist.id, cover_file_id: uploaded.id }); onClose(); };
    return <div className="fixed inset-0 z-[160] flex items-end bg-black/70 backdrop-blur-sm" onClick={onClose}><div className="mx-auto max-h-[80vh] w-full max-w-2xl rounded-t-3xl border border-white/10 bg-dark-900 p-4" onClick={e=>e.stopPropagation()}><div className="flex items-center justify-between"><h2 className="text-lg font-bold">انتخاب عکس پلی‌لیست</h2><div className="flex items-center gap-2"><label className="btn-secondary flex h-9 cursor-pointer items-center gap-1.5 px-3 text-xs"><Upload className="h-3.5 w-3.5"/> آپلود عکس<input type="file" accept="image/*" className="hidden" onChange={uploadCover} /></label><button className="btn-icon" onClick={onClose}><X className="h-5 w-5"/></button></div></div><div className="mt-4 grid max-h-[60vh] grid-cols-3 gap-3 overflow-y-auto sm:grid-cols-5">{(data?.files || []).map(file => <button key={file.id} disabled={update.isPending || upload.isPending} onClick={async () => { await update.mutateAsync({ id: playlist.id, cover_file_id: file.id }); onClose(); }} className={`overflow-hidden rounded-xl border ${playlist.cover_file_id === file.id ? 'border-primary-400 ring-2 ring-primary-500/30' : 'border-white/10'}`}><img loading="lazy" decoding="async" src={`${file.stream_url}${file.stream_url.includes('?') ? '&' : '?'}token=${encodeURIComponent(localStorage.getItem('access_token') || '')}`} className="aspect-square w-full object-cover"/><span className="block truncate p-1 text-[10px]">{file.file_name}</span></button>)}</div>{!data?.files.length && <p className="py-10 text-center text-sm text-dark-400">هنوز عکس تصویری در کمد نداری.</p>}</div></div>;
}

function EditPlaylist({ playlist, close }: { playlist: Playlist; close: () => void }) { const update=useUpdatePlaylist(); return <PlaylistEditor title="ویرایش پلی‌لیست" initialName={playlist.name} initialDescription={playlist.description||''} onClose={close} onSave={async(name,description)=>{await update.mutateAsync({id:playlist.id,name,description});close()}}/>; }
function PlaylistEditor({ title, initialName='', initialDescription='', onClose, onSave }: { title:string; initialName?:string; initialDescription?:string; onClose:()=>void; onSave:(name:string,description:string)=>Promise<void> }) {
    const [name,setName]=useState(initialName); const [description,setDescription]=useState(initialDescription); const [saving,setSaving]=useState(false);
    return <div className="fixed inset-0 z-[170] flex items-center justify-center bg-black/70 p-4" onClick={onClose}><form className="w-full max-w-md rounded-2xl border border-white/10 bg-dark-900 p-5" onClick={e=>e.stopPropagation()} onSubmit={async e=>{e.preventDefault();if(!name.trim())return;setSaving(true);try{await onSave(name.trim(),description.trim())}finally{setSaving(false)}}}>
        <div className="flex items-center justify-between"><h2 className="text-lg font-bold">{title}</h2><button type="button" className="btn-icon" onClick={onClose}><X className="h-5 w-5"/></button></div><input autoFocus maxLength={255} className="input mt-4 w-full" placeholder="نام پلی‌لیست" value={name} onChange={e=>setName(e.target.value)}/><textarea maxLength={1024} className="input mt-3 min-h-24 w-full" placeholder="توضیحات (اختیاری)" value={description} onChange={e=>setDescription(e.target.value)}/><button disabled={saving||!name.trim()} className="btn-primary mt-4 flex w-full items-center justify-center gap-2"><Save className="h-4 w-4"/>{saving?'در حال ذخیره…':'ذخیره'}</button>
    </form></div>;
}
